  function fusionner(Dn) { Object.keys(Dn || {}).forEach(function (k) { var r = D[k] || (D[k] = ['', '', '', '', '', '']), n = Dn[k] || []; for (var i = 0; i < 6; i++) if (n[i]) r[i] = n[i]; }); }

  /* ── Normalisation identique au moteur de Pilotage (trNorm) ── */
  function norm(x) { return String(x == null ? '' : x).replace(/[   ]/g, ' ').replace(/\s+([:;!?%])/g, ' $1').replace(/[ \t]+/g, ' '); }

